UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Anthony Santos, known as Romeo Santos, is a bachata singer, composer and producer born in the Bronx on 21 July 1981 to a Dominican father and a Puerto Rican mother. As lead voice and songwriter of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"659a3fd8-511f-4fbf-8f02-4515db900bb1"}},{"text":" he rebuilt bachata around hip hop and R&B and carried it onto European charts; as a soloist he became the first Latin artist to headline Yankee Stadium and MetLife Stadium. He is widely called the King of Bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Tinellers","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The group formed in the Bronx in the early 1990s around the brothers Lenny and Max Santos, who recruited Anthony and his cousin ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8dcfc4e1-9af4-4378-9e19-52573af429a7","displayText":"Henry Santos","occurrenceId":"6b956c32-c08b-47b7-b03c-d4331055c941"}},{"text":". They called themselves «Los Tinellers», the word teenagers spelled as it sounds in Spanish, and their «Trampa de Amor» (1996) sold almost nothing. The manager Julio César García renamed them ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"dbdcbe1d-fc67-4440-a32c-951e96ac06a4"}},{"text":", and in 1998 the group signed to «Premium Latin Music».","type":"text"}]},{"type":"paragraph","content":[{"text":"Anthony took the stage name Romeo partly because his own was already taken: ","type":"text"},{"type":"artistReference","attrs":{"artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos","occurrenceId":"21cda1f1-4ffd-4f02-a3bf-d09721c0b773"}},{"text":" had been recording as Anthony Santos since the late 1980s.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Obsesión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Generation Next» (1999) reworked «Cuándo Volverás» into the group''s debut single, but the turn came with «We Broke the Rules» (2002) and «Obsesión», a duet with Judy Santos. In the United States it reached only number 32 on the tropical chart; in Europe it went to number one in seven countries and held the top of the Italian chart for sixteen consecutive weeks — a bachata sung in Spanish, on Italian radio, by four men from the Bronx.","type":"text"}]},{"type":"paragraph","content":[{"text":"What they had changed was the arrangement: Lenny Santos ran the requinto through wah, phaser and harmonizer, Max Santos played bass with slaps and rock riffs, and the lyrics moved between Spanish and English. The sound was named bachata urbana, and most of the genre has been written in it since.","type":"text"}]},{"type":"paragraph","content":[{"text":"The decade of Aventura","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Love & Hate» (2003) produced «Hermanita». «God''s Project» (2005), the first album distributed by «Sony Music Latin», carried «Un Beso» and «Ella y Yo», a duet with Don Omar that pulled a reggaetón audience into bachata. «K.O.B. Live» (2006) gave «Mi Corazoncito», and «The Last» (2009) opened with «Por un Segundo», the group''s first number one on the Hot Latin Songs chart.","type":"text"}]},{"type":"paragraph","content":[{"text":"In 2007 ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"50c3d861-0d53-4352-a282-c6069eff5c8f"}},{"text":" became the first bachata act to sell out Madison Square Garden. By 2011 it had sold more than 1.7 million records in the United States on five studio albums in a decade, and Santos held twelve ASCAP awards for songs he had written for it. The group separated that year.","type":"text"}]},{"type":"paragraph","content":[{"text":"The «Fórmula» trilogy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Santos signed with «Sony Music Latin» in 2011 and released «Fórmula, Vol. 1» that November; «Promise», with Usher, is certified diamond. «Fórmula, Vol. 2» (2014) is the commercial peak: «Propuesta Indecente» spent 125 weeks on the Hot Latin Songs chart, and «Odio» was the first record on which Drake sang in Spanish. «Golden» (2017) followed with «Héroe Favorito» and «Imitadora».","type":"text"}]},{"type":"paragraph","content":[{"text":"«Fórmula, Vol. 3» (2022) closed the trilogy, with «Sin Fin» alongside Justin Timberlake, «El Pañuelo» with Rosalía, and «15,500 Noches», a merengue recorded with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"556e95ab-b6e9-4e71-bd81-2556006ea3ff"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"cf7ebc97-2b1d-4832-ac6c-57b09220ba3b"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fc762d4-96b8-4ecf-aca8-fdf52936658e","displayText":"Toño Rosario","occurrenceId":"66f7d9c7-d793-482a-8949-318c9dd0d7c4"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"occurrenceId":"9cebe8c9-bde9-41a9-af93-8f9f456d155a","artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando"}},{"text":". It won the 2023 Latin Grammy for best merengue and/or bachata album, in a tie with «A Mi Manera» by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"7f414f77-27fc-4537-a2cf-c570139d0784"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"«Utopía»","type":"text","marks"