7f216f19-be38-4369-adb6-0f51922cb75c","displayText":"Ala Jaza","occurrenceId":"a0742268-f6ad-488c-a4c8-399f755d404b"}},{"text":", part of a scene that also counts ","type":"text"},{"type":"artistReference","attrs":{"artistId":"559f2ed4-8831-483b-bc00-7cb4f340ad92","displayText":"El Alfa","occurrenceId":"d9ec46a3-ee2a-450d-a20f-f3d67a89fe47"}},{"text":" among its biggest names.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"More than two decades into a career built on merengue de calle’s crossover into dembow, Sujeto Oro 24 remains one of the genre’s recognizable, if combative, voices, as comfortable trading verses on a posse cut as fronting a tribute to the salsa greats he grew up on.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'sujeto-oro-24' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Sujeto Oro 24, born Johan Manuel Nova in Santo Domingo, is a Dominican merengue de calle and dembow-crossover singer known for his aggressive, streetwise delivery and his identification with his home barrio of Los Mina.

**Merengue de calle**

Coming up alongside genre pioneers such as Omega, he built a catalogue of dancefloor hits, among them «Weje Weje», «Bobo» and «Amor», and paid tribute to his own barrio directly on «Los Mina Lo Mato» (2022). He has kept a foothold in tribute and live-band shows as well, fronting homages to salsa’s Tito Rojas and to Ramón Orlando.

**Posse cuts and collaborations**

He has been a regular presence on the genre’s crowded remix cuts, appearing alongside Don Miguelo and Mozart La Para on the remixes of «A Beber» and «Pa Que Me Dan De Eso», and recording «No Me Importa» with Ala Jaza, part of a scene that also counts El Alfa among its biggest names.

**Legacy**

More than two decades into a career built on merengue de calle’s crossover into dembow, Sujeto Oro 24 remains one of the genre’s recognizable, if combative, voices, as comfortable trading verses on a posse cut as fronting a tribute to the salsa greats he grew up on.' WHERE slug = 'sujeto-oro-24';
