UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Manuel Rivera, known as Tulile and billed as El Rey Tulile, is a Dominican singer, saxophonist and composer. He is one of the principal names of merengue de calle, the fast, danceable and deliberately irreverent street form of merengue that took hold at the turn of the century.","type":"text"}]},{"type":"paragraph","content":[{"text":"The saxophone","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born in Santo Domingo in 1976 and began studying music as a teenager, learning the saxophone at fourteen. The instrument, rather than his voice, is what first gave him a living.","type":"text"}]},{"type":"paragraph","content":[{"text":"The orchestras","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He worked his way through the salaried circuit before fronting anything of his own. He played in the orchestra of the Santo Domingo fire brigade, then was hired by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"fb2c703f-5362-47dd-ada0-7c6d5e106f3b","displayText":"Dioni Fernández y El Equipo","occurrenceId":"9ecd860a-168d-468e-9eb4-f04a5c9eee2d"}},{"text":", then moved to the orchestra of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"97249298-9041-4d41-904c-2c788ac2963e","displayText":"Monchy Capricho","occurrenceId":"be8ec680-47e0-432c-9073-2502810b0bc3"}},{"text":", and then to ","type":"text"},{"type":"artistReference","attrs":{"occurrenceId":"350d77e9-6e9a-4c0a-bb49-dbaaac7cb10b","artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando"}},{"text":". That is the standard route of a Dominican section player, and it accounts for the trained musicianship behind a genre usually described as raw.","type":"text"}]},{"type":"paragraph","content":[{"text":"On his own","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"At the end of the nineties he left the orchestras to record under his own name, choosing a deliberately provocative register: fast rhythm, comic lyrics and a steady undercurrent of double meaning. His second album, released in 2000, carried La Cuca, the record that made his name across the country.","type":"text"}]},{"type":"paragraph","content":[{"text":"Susana, Una Culebra, Tan Buena, Conmigo No and Presumida followed, and the formula held: the songs are built to be danced and repeated rather than contemplated.","type":"text"}]},{"type":"paragraph","content":[{"text":"The costumes","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His stage presentation has drawn as much comment as the music. He has appeared in nappies, in a pharaoh’s costume and in a bridal gown, treating the concert as a spectacle in which the outfit is part of the joke.","type":"text"}]},{"type":"paragraph","content":[{"text":"Working from abroad","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He moved to the United States in November 2011 and has continued to record and tour from there. His recent output includes merengue adaptations of hits from other genres, a practice that has kept his catalogue in circulation with younger audiences.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'tulile' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'José Manuel Rivera, known as Tulile and billed as El Rey Tulile, is a Dominican singer, saxophonist and composer. He is one of the principal names of merengue de calle, the fast, danceable and deliberately irreverent street form of merengue that took hold at the turn of the century.

**The saxophone**

He was born in Santo Domingo in 1976 and began studying music as a teenager, learning the saxophone at fourteen. The instrument, rather than his voice, is what first gave him a living.

**The orchestras**

He worked his way through the salaried circuit before fronting anything of his own. He played in the orchestra of the Santo Domingo fire brigade, then was hired by Dioni Fernández y El Equipo, then moved to the orchestra of Monchy Capricho, and then to Ramón Orlando. That is the standard route of a Dominican section player, and it accounts for the trained musicianship behind a genre usually described as raw.

**On his own**

At the end of the nineties he left the orchestras to record under his own name, choosing a deliberately provocative register: fast rhythm, comic lyrics and a steady undercurrent of double meaning. His second album, released in 2000, carried La Cuca, the record that made his name across the country.

Susana, Una Culebra, Tan Buena, Conmigo No and Presumida followed, and the formula held: the songs are built to be danced and repeated rather than contemplated.

**The costumes**

His stage presentation has drawn as much comment as the music. He has appeared in nappies, in a pharaoh’s costume and in a bridal gown, treating the concert as a spectacle in which the outfit is part of the joke.

**Working from abroad**

He moved to the United States in November 2011 and has continued to record and tour from there. His recent output includes merengue adaptations of hits from other genres, a practice that has kept his catalogue in circulation with younger audiences.' WHERE slug = 'tulile';
